CREATE TRIGGER [dbo].[Update_Comment_On_TimeGroup]
 ON [dbo].[TimeGroup]
 AFTER INSERT
 AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @id nvarchar(100)
  SELECT @id = Id from inserted
  DECLARE @comment nvarchar(100)
  SELECT @comment = Comment from inserted

  IF @comment = 'trigger'
    BEGIN
      UPDATE dbo.TimeGroup
      SET Comment = 'happy'
      WHERE id = @id
    END
END

GO
ALTER TABLE [dbo].[TimeGroup] ENABLE TRIGGER [Update_Comment_On_TimeGroup]
GO

